      "path": ".github/workflows/validate-pr.yml",
      "content": "name: Validate PR\n\non:\n  pull_request_target:\n    types: [opened, synchronize, reopened]\n  # NOTE: intentionally no `paths:` filter. The `validate` check is a required\n  # status check on `main`; if the workflow is skipped for a PR that doesn't\n  # touch the README files, the check never reports and the PR is permanently\n  # unmergeable. Instead we always run and short-circuit inside the job.\n\npermissions:\n  contents: read\n  pull-requests: write\n\nconcurrency:\n  group: validate-pr-${{ github.event.pull_request.number }}\n  cancel-in-progress: true\n\njobs:\n  validate:\n    runs-on: ubuntu-latest\n    steps:\n      - name: Checkout base\n        uses: actions/checkout@v4\n        with:\n          fetch-depth: 0\n\n      - name: Fetch PR head\n        env:\n          PR_NUM: ${{ github.event.pull_request.number }}\n        run: |\n          git fetch origin \"pull/${PR_NUM}/head:pr-head\"\n          base_sha=\"$(git merge-base origin/${{ github.base_ref }} pr-head)\"\n          echo \"BASE_SHA=$base_sha\" >> \"$GITHUB_ENV\"\n\n          # Does this PR touch the curated list files at all?\n          if git diff --name-only \"$base_sha\" pr-head \\\n               | grep -qE '^(README\\.md|README\\.zh-CN\\.md)$'; then\n            echo \"IS_LIST_PR=true\" >> \"$GITHUB_ENV\"\n          else\n            echo \"IS_LIST_PR=false\" >> \"$GITHUB_ENV\"\n            echo \"This PR does not touch README.md / README.zh-CN.md.\"\n            echo \"Skipping list-entry validation (nothing to check).\"\n          fi\n\n      - name: Check changed files scope\n        if: env.IS_LIST_PR == 'true'\n        env:\n          BASE_SHA: ${{ env.BASE_SHA }}\n        run: |\n          changed=$(git diff --name-only \"$BASE_SHA\" pr-head)\n          echo \"Changed files:\"\n          echo \"$changed\"\n          bad=$(echo \"$changed\" | grep -v -E '^(README\\.md|README\\.zh-CN\\.md)$' || true)\n          if [ -n \"$bad\" ]; then\n            echo \"::error::This PR touches files outside the README list files:\"\n            echo \"$bad\" | sed 's/^/  - /'\n            echo \"::error::List submissions should only modify README.md and/or README.zh-CN.md.\"\n            exit 1\n          fi\n\n      - name: Validate new entries\n        id: validate\n        if: env.IS_LIST_PR == 'true'\n        env:\n          BASE_SHA: ${{ env.BASE_SHA }}\n          GH_TOKEN: ${{ secrets.GITHUB_TOKEN }}\n        run: |\n          set -uo pipefail\n\n          # Collect added lines that look like list entries\n          git diff --unified=0 \"$BASE_SHA\" pr-head -- README.md README.zh-CN.md \\\n            | grep -E '^\\+' | grep -v -E '^\\+\\+\\+' | sed 's/^+//' > /tmp/added.txt || true\n\n          grep -E '^\\s*-\\s*\\[' /tmp/added.txt > /tmp/entries.txt || true\n\n          added_count=$(wc -l < /tmp/entries.txt | tr -d ' ')\n          echo \"Added entry lines: $added_count\"\n\n          if [ \"$added_count\" = \"0\" ]; then\n            echo \"No new list entries detected — nothing to validate.\"\n            echo \"result=noentries\" >> \"$GITHUB_OUTPUT\"\n            exit 0\n          fi\n\n          fail=0\n          : > /tmp/report.md\n\n          while IFS= read -r line; do\n            [ -z \"$line\" ] && continue\n            echo \"::group::$line\"\n\n            # --- skip table-of-contents anchor rows: `- [Section](#anchor)`.\n            #     These are in-page TOC links, not list entries, and legitimately\n            #     fail the `- [Name](https://url)` format rule below.\n            if echo \"$line\" | grep -qE '^\\s*-\\s*\\[[^]]+\\]\\(#[^)]*\\)\\s*$'; then\n              echo \"TOC anchor row, skipping: $line\"\n              echo \"::endgroup::\"\n              continue\n            fi\n\n            # --- format check: - [Name](url) — description.\n            if ! echo \"$line\" | grep -qE '^\\s*-\\s*\\[[^]]+\\]\\(https?://[^)]+\\)'; then\n              echo \"::error::Bad entry format: $line\"\n              echo \"- ❌ **Format** — not \\`- [Name](https://link) — description.\\`: \\`$(echo \"$line\" | head -c 120)\\`\" >> /tmp/report.md\n              fail=1\n              echo \"::endgroup::\"\n              continue\n            fi\n\n            url=$(echo \"$line\" | sed -nE 's/.*\\]\\((https?:\\/\\/[^)]+)\\).*/\\1/p' | head -1)\n            desc=$(echo \"$line\" | sed -E 's/^\\s*-\\s*\\[[^]]+\\]\\([^)]+\\)//')\n\n            # --- description present\n            clean_desc=$(echo \"$desc\" | sed -E 's/`⭐[0-9]+`//g' | sed -E 's/[[:space:]—–-]//g')\n            if [ -z \"$clean_desc\" ]; then\n              echo \"::error::Missing description: $line\"\n              echo \"- ❌ **Description** — entry has no description text: $url\" >> /tmp/report.md\n              fail=1\n            fi\n\n            # --- link reachable\n            code=$(curl -sS -o /dev/null -w '%{http_code}' -L --max-time 25 \\\n                    -H 'User-Agent: dsh-list-bot' \"$url\" 2>/dev/null || echo 000)\n            echo \"HTTP $code for $url\"\n            if [ \"$code\" = \"404\" ] || [ \"$code\" = \"410\" ] || [ \"$code\" = \"000\" ]; then\n              echo \"::error::Link unreachable (HTTP $code): $url\"\n              echo \"- ❌ **Link** — unreachable (HTTP \\`$code\\`): $url\" >> /tmp/report.md\n              fail=1\n              echo \"::endgroup::\"\n              continue\n            fi\n\n            # --- GitHub repo: check dsh topic\n            if echo \"$url\" | grep -qE '^https?://github\\.com/[^/]+/[^/]+/?$'; then\n              slug=$(echo \"$url\" | sed -E 's#^https?://github\\.com/##; s#/$##')\n              topics=$(gh api \"repos/$slug\" --jq '.topics | join(\",\")' 2>/dev/null || echo \"__ERR__\")\n              if [ \"$topics\" = \"__ERR__\" ]; then\n                echo \"::warning::Could not read topics for $slug\"\n                echo \"- ⚠️ **Topic** — could not read topics for \\`$slug\\` (private/renamed?)\" >> /tmp/report.md\n              elif echo \"$topics\" | grep -qE '(^|,)(dsh|dsh-plugin|dsh-skill|deepseek-harness)(,|$)'; then\n                echo \"dsh topic OK ($topics)\"\n              else\n                echo \"::warning::No dsh topic on $slug (topics: $topics)\"\n                echo \"- ⚠️ **Topic** — \\`$slug\\` has no \\`dsh\\` / \\`deepseek-harness\\` topic (found: \\`${topics:-none}\\`). Please add the \\`dsh\\` topic to your repo.\" >> /tmp/report.md\n                fail=1\n              fi\n            fi\n\n            echo \"::endgroup::\"\n          done < /tmp/entries.txt\n\n          if [ \"$fail\" != \"0\" ]; then\n            echo \"result=fail\" >> \"$GITHUB_OUTPUT\"\n          else\n            echo \"result=pass\" >> \"$GITHUB_OUTPUT\"\n          fi\n          exit \"$fail\"\n\n      - name: Comment findings\n        if: always() && steps.validate.outputs.result == 'fail'\n        env:\n          GH_TOKEN: ${{ secrets.GITHUB_TOKEN }}\n          PR_NUM: ${{ github.event.pull_request.number }}\n          REPO: ${{ github.repository }}\n        run: |\n          {\n            echo \"🐋 **Automated list check found issues**\"\n            echo\n            cat /tmp/report.md\n            echo\n            echo \"<details><summary>How to fix</summary>\"\n            echo\n            echo \"- **Format:** \\`- [Name](https://link) — Concise one-line description.\\`\"\n            echo \"- **Topic:** your repo needs the \\`dsh\\` GitHub topic (Settings → About → Topics).\"\n            echo \"- **Scope:** only \\`README.md\\` / \\`README.zh-CN.md\\` should be touched.\"\n            echo \"- Push a fix to the same branch and this check re-runs automatically.\"\n            echo\n            echo \"</details>\"\n          } > /tmp/comment.md\n          gh pr comment \"$PR_NUM\" --repo \"$REPO\" --body-file /tmp/comment.md\n"
    },
    {
      "path": ".github/workflows/check-duplicates.yml",
      "content": "name: Check Duplicates\n\n# Compare per-language, per-category URL counts against the PR merge base.\n# Only increases in duplicate rows are reported; existing duplicates and\n# cross-category listings are left alone. Findings are advisory, not a gate.\non:\n  pull_request_target:\n    types: [opened, synchronize, reopened]\n\npermissions:\n  contents: read\n  pull-requests: write\n\nconcurrency:\n  group: check-duplicates-${{ github.event.pull_request.number }}\n  cancel-in-progress: true\n\njobs:\n  check:\n    runs-on: ubuntu-latest\n    continue-on-error: true\n    if: github.repository == 'Dominic789654/awesome-deepseek-harness'\n    steps:\n      - name: Checkout trusted base only\n        uses: actions/checkout@v4\n        with:\n          ref: ${{ github.event.pull_request.base.sha }}\n          fetch-depth: 0\n          persist-credentials: false\n\n      - name: Fetch PR data without checking it out\n        env:\n          PR_NUM: ${{ github.event.pull_request.number }}\n          HEAD_SHA: ${{ github.event.pull_request.head.sha }}\n        run: |\n          set -euo pipefail\n          git fetch --no-tags origin \"pull/${PR_NUM}/head\"\n          # A newer push must not be reported as if it were this event's head.\n          test \"$(git rev-parse FETCH_HEAD)\" = \"$HEAD_SHA\"\n          base_sha=\"$(git merge-base HEAD \"$HEAD_SHA\")\"\n          echo \"BASE_SHA=$base_sha\" >> \"$GITHUB_ENV\"\n\n      - name: Detect duplicate entries\n        id: detect\n        env:\n          HEAD_SHA: ${{ github.event.pull_request.head.sha }}\n        run: |\n          python3 - <<'PY'\n          import html\n          import os\n          import re\n          import subprocess\n          import uuid\n          from collections import Counter\n          from urllib.parse import urlsplit\n\n          FILES = ('README.md', 'README.zh-CN.md')\n          SKIP = {\n              'Quick Start', 'Contents', 'Contributing', 'Star History', 'License',\n              '快速开始', '目录', '贡献指南', 'Star 趋势', '许可',\n          }\n          ENTRY = re.compile(r'^\\s*-\\s+\\[[^\\]]+\\]\\((https?://[^\\s)]+)\\)', re.I)\n\n          def key_of(url):\n              url = url.strip().rstrip('/')\n              try:\n                  parsed = urlsplit(url)\n              except ValueError:\n                  return url.lower()\n              parts = parsed.path.strip('/').split('/')\n              if parsed.hostname and parsed.hostname.lower() == 'github.com' and len(parts) >= 2:\n                  # GitHub project identity ignores branch/subpath/query/fragment.\n                  return '/'.join(parts[:2]).lower().removesuffix('.git')\n              return url.lower()\n\n          def index(text):\n              counts = Counter()\n              section = None\n              fence = None\n              for line in text.splitlines():\n                  stripped = line.lstrip()\n                  if fence:\n                      if re.fullmatch(re.escape(fence[0]) + '{' + str(len(fence)) + r',}\\s*', stripped):\n                          fence = None\n                      continue\n                  if match := re.match(r'(`{3,}|~{3,})', stripped):\n                      fence = match.group(1)\n                      continue\n                  if line.startswith('## '):\n                      section = line[3:].strip()\n                      continue\n                  if section is not None and section not in SKIP:\n                      if match := ENTRY.match(line):\n                          counts[(section, key_of(match.group(1)))] += 1\n              return counts\n\n          def read_at(sha, filename):\n              # Read blobs only: never checkout, import or execute PR content.\n              paths = subprocess.check_output(\n                  ['git', 'ls-tree', '--name-only', sha, '--', filename], text=True)\n              if filename not in paths.splitlines():\n                  return ''\n              return subprocess.check_output(\n                  ['git', 'show', f'{sha}:{filename}'], text=True, encoding='utf-8')\n\n          def safe(text):\n              # Render PR-controlled text literally, without Markdown or mentions.\n              return ''.join(f'&#{ord(c)};' if c in '`*_[]()@#!|\\\\' else html.escape(c)\n                             for c in text[:200])\n\n          findings = []\n          for filename in FILES:\n              before = index(read_at(os.environ['BASE_SHA'], filename))\n              after = index(read_at(os.environ['HEAD_SHA'], filename))\n              for (section, key), count in sorted(after.items()):\n                  old = before[(section, key)]\n                  increase = max(0, count - 1) - max(0, old - 1)\n                  if increase > 0:\n                      findings.append(\n                          f'- ⚠️ **{filename}** / {safe(section)}: {safe(key)} '\n                          f'— {old} → {count} rows (+{increase} duplicate rows).')\n\n          shown = []\n          size = 0\n          for finding in findings[:50]:\n              if size + len(finding) > 40000:\n                  break\n              shown.append(finding)\n              size += len(finding) + 1\n          report = '\\n'.join(shown)\n          if len(shown) < len(findings):\n              report += f'\\n- Showing {len(shown)} of {len(findings)} affected URL/category groups.'\n          # A guaranteed newline before the delimiter is required even for zero findings.\n          delimiter = 'REPORT_' + uuid.uuid4().hex\n          with open(os.environ['GITHUB_OUTPUT'], 'a', encoding='utf-8') as output:\n              output.write(f'report<<{delimiter}\\n{report}\\n{delimiter}\\ncount={len(findings)}\\n')\n          print(f'Duplicate URL/category groups increased: {len(findings)}')\n          PY\n\n      - name: Create or update advisory comment\n        uses: actions/github-script@v7\n        env:\n          REPORT: ${{ steps.detect.outputs.report }}\n          COUNT: ${{ steps.detect.outputs.count }}\n        with:\n          script: |\n            const marker = '<!-- dsh-duplicate-entry-check -->';\n            const issue = { ...context.repo, issue_number: context.issue.number };\n            // Do not let an obsolete run overwrite a newer head's advisory.\n            const { data: pr } = await github.rest.pulls.get({\n              ...context.repo, pull_number: context.issue.number\n            });\n            if (pr.head.sha !== context.payload.pull_request.head.sha) return;\n            const comments = await github.paginate(github.rest.issues.listComments, {\n              ...issue, per_page: 100\n            });\n            const existing = comments.find(c =>\n              c.user?.type === 'Bot' && c.user?.login === 'github-actions[bot]' &&\n              c.body?.startsWith(marker));\n            if (!/^\\d+$/.test(process.env.COUNT || '')) throw new Error('Missing detector count');\n            const count = Number(process.env.COUNT);\n            if (count === 0 && !existing) return;\n            const summary = count > 0\n              ? `🐋 **Duplicate-entry check**: ${count} URL/category group(s) gained duplicate rows.\\n\\n${process.env.REPORT}`\n              : '🐋 **Duplicate-entry check cleared**: no same-category duplicate counts increased.';\n            const body = `${marker}\\n${summary}\\n\\n` +\n              'Each README language is checked separately against the PR merge base. ' +\n              'Cross-category listings, description-only edits and unchanged historical duplicates are not flagged.\\n\\n' +\n              'Remove extra same-category rows (a name/description change alone is not a fix). ' +\n              'This advisory comment is updated on the next push, including when findings clear. ' +\n              'Findings do not block merging.';\n            if (existing) {\n              if (existing.body !== body) await github.rest.issues.updateComment({\n                ...context.repo, comment_id: existing.id, body\n              });\n            } else {\n              await github.rest.issues.createComment({ ...issue, body });\n            }\n"
    },
    {
      "path": ".scripts/dsh_recent_added.py",
      "content": "#!/usr/bin/env python3\n\"\"\"Regenerate the '🆕 Recently added' block in both READMEs from git history (last 7 days).\n\nIdempotent: rewrites only the text between <!-- RECENT-ADDED:START --> / <!-- RECENT-ADDED:END -->.\nUsage: python3 .scripts/dsh_recent_added.py [--days 7] [--limit 12]\n\"\"\"\nimport argparse, pathlib, re, subprocess\n\nREPO = pathlib.Path(__file__).resolve().parent.parent\nSTART, END = \"<!-- RECENT-ADDED:START -->\", \"<!-- RECENT-ADDED:END -->\"\nENTRY = re.compile(r\"^\\+\\s*-\\s*\\[[^\\]]+\\]\\(https?://[^\\s)]+\\)\")\n\n\ndef recent(days, limit):\n    \"\"\"Added README entry lines in the last N days (newest commits first).\"\"\"\n    r = subprocess.run([\"git\", \"log\", f\"--since={days} days ago\", \"--pretty=format:@@%H%x09%ad\",\n                        \"--date=short\", \"-p\", \"--unified=0\", \"--\", \"README.md\"],\n                       cwd=REPO, text=True, capture_output=True)\n    out, seen, commit = [], set(), None\n    for line in r.stdout.splitlines():\n        if line.startswith(\"@@\"):\n            commit = line[2:]\n        elif ENTRY.match(line):\n            entry = line[1:].strip()\n            key = entry.split(\"](\")[0]\n            if key not in seen:\n                seen.add(key)\n                out.append((commit, entry))\n    return out[:limit], len(out)\n\n\ndef rewrite(path, items, total, days):\n    t = path.read_text(encoding=\"utf-8\")\n    if START not in t or END not in t:\n        print(f\"{path.name}: markers missing, skip\"); return\n    if \"Recently added\" in t:\n        title, note = \"🆕 Recently added (last %d days)\" % days, \"_auto-generated by `.scripts/dsh_recent_added.py`_\"\n    else:\n        title, note = \"🆕 最近新增（近 %d 天）\" % days, \"_由 `.scripts/dsh_recent_added.py` 自动生成_\"\n    body = \"\\n\".join(i[1] for i in items)\n    more = \"\" if total <= len(items) else f\"\\n\\n_…and {total - len(items)} more this week._\"\n    block = f\"{START}\\n<details>\\n<summary>{title}</summary>\\n\\n{note}\\n\\n{body}{more}\\n\\n</details>\\n{END}\"\n    t = re.sub(re.escape(START) + r\".*?\" + re.escape(END), block, t, flags=re.S)\n    path.write_text(t, encoding=\"utf-8\")\n    print(f\"{path.name}: wrote {len(items)}/{total} entries\")\n\n\nif __name__ == \"__main__\":\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\"--days\", type=int, default=7)\n    ap.add_argument(\"--limit\", type=int, default=12)\n    a = ap.parse_args()\n    items, total = recent(a.days, a.limit)\n    for f in (\"README.md\", \"README.zh-CN.md\"):\n        rewrite(REPO / f, items, total, a.days)\n"
    },
    {
      "path": ".scripts/annotate_stars.py",
      "content": "#!/usr/bin/env python3\n\"\"\"Annotate README entries with a ⭐ star badge for notable repos (>=10 stars).\nNon-destructive: only appends a badge to existing entry lines; never deletes entries.\nIdempotent: strips any existing ' ⭐N' / ' `⭐N`' badge before re-adding.\n\"\"\"\nimport re, sys, pathlib\n\nSTARS_FILE = pathlib.Path.home() / \"awesome-deepseek-harness\" / \".stars-snapshot.tsv\"\nTHRESHOLD = 10\n\n# load stars: full_name -> stars\nstars = {}\nfor line in STARS_FILE.read_text().splitlines():\n    parts = line.split(\"\\t\")\n    if len(parts) >= 2 and parts[1].isdigit():\n        stars[parts[0].lower()] = int(parts[1])\n\nbadge_re = re.compile(r\"\\s*`?⭐[\\d,]+`?\")           # existing badge to strip\nentry_re = re.compile(r\"^(- \\[)([^\\]]+)(\\]\\()(https://github\\.com/([A-Za-z0-9._-]+/[A-Za-z0-9._-]+))\")\n\ndef process(path):\n    p = pathlib.Path(path)\n    out = []\n    changed = 0\n    for line in p.read_text().splitlines():\n        m = entry_re.match(line)\n        if m:\n            repo = m.group(5).lower()\n            st = stars.get(repo)\n            # strip any existing badge first (idempotent)\n            line = badge_re.sub(\"\", line)\n            if st is not None and st >= THRESHOLD:\n                # append badge at end of the line\n                line = line.rstrip() + f\"  `⭐{st}`\"\n                changed += 1\n        out.append(line)\n    p.write_text(\"\\n\".join(out) + \"\\n\")\n    return changed\n\nif __name__ == \"__main__\":\n    for f in [\"README.md\", \"README.zh-CN.md\"]:\n        fp = pathlib.Path.home() / \"awesome-deepseek-harness\" / f\n        n = process(fp)\n        print(f\"{f}: badged {n} entries\")\n"
    },
    {
      "path": ".github/workflows/star-history.yml",
      "content": "name: Star History\n\n# Samples this repo's own star total once a day and regenerates a self-hosted SVG\n# chart. Needed because GitHub restricted the public stargazers API on 2026-06-30\n# (https://github.blog/changelog/2026-06-30-upcoming-access-restrictions-to-public-api-endpoints-and-ui-views/),\n# which broke third-party embedded charts (star-history.com) for repos those\n# services do not collaborate on. The plain star count is still readable, so we\n# build the curve ourselves from daily samples.\n\non:\n  schedule:\n    # 01:15 UTC daily (09:15 Asia/Shanghai). Offset from :00 to dodge scheduler spikes.\n    - cron: \"15 1 * * *\"\n  workflow_dispatch:\n\npermissions:\n  contents: write\n\nconcurrency:\n  group: star-history\n  cancel-in-progress: false\n\njobs:\n  sample:\n    runs-on: ubuntu-latest\n    # Never run on forks: it would try to push and would chart the wrong repo.\n    if: github.repository == 'Dominic789654/awesome-deepseek-harness'\n    steps:\n      - name: Checkout\n        uses: actions/checkout@v4\n\n      - name: Record today's star count and render chart\n        env:\n          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}\n        run: python3 .scripts/star_history.py\n\n      - name: Commit if changed\n        run: |\n          set -euo pipefail\n          if git diff --quiet -- assets/star-history.tsv assets/star-history.svg; then\n            echo \"No change in star history; nothing to commit.\"\n            exit 0\n          fi\n          git config user.name \"github-actions[bot]\"\n          git config user.email \"41898282+github-actions[bot]@users.noreply.github.com\"\n          git add assets/star-history.tsv assets/star-history.svg\n          stars=\"$(tail -1 assets/star-history.tsv | cut -f2)\"\n          git commit -m \"chore: star history sample $(date -u +%Y-%m-%d) (${stars} stars)\"\n          # Rebase onto any commits that landed while this job ran, then push.\n          for attempt in 1 2 3; do\n            if git push origin HEAD:main; then\n              echo \"pushed on attempt ${attempt}\"\n              exit 0\n            fi\n            echo \"push rejected; rebasing and retrying (attempt ${attempt})\"\n            git pull --rebase --autostash origin main\n          done\n          echo \"::error::failed to push star history after 3 attempts\"\n          exit 1\n"
    },
