      "path": "plugins/dsh-viz/package.json",
      "content": "{\n  \"name\": \"dsh-viz\",\n  \"description\": \"Visualization tool for DeepSeek Harness: chart_render turns structured data into a self-contained ECharts HTML artifact inside the active workspace.\",\n  \"version\": \"0.1.0\",\n  \"license\": \"MIT\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"files\": [\n    \"lib\",\n    \"cordis.patch.yml\",\n    \"dsh.plugin.json\",\n    \"README.md\",\n    \"LICENSE\"\n  ],\n  \"scripts\": {\n    \"build\": \"tsc -p tsconfig.json\",\n    \"typecheck\": \"tsc -p tsconfig.json --noEmit\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"*\",\n    \"@deepseek-ai/dsh-tools\": \"*\",\n    \"@deepseek-ai/schemastery\": \"*\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": { \"optional\": true },\n    \"@deepseek-ai/dsh-tools\": { \"optional\": true },\n    \"@deepseek-ai/schemastery\": { \"optional\": true }\n  },\n  \"devDependencies\": {\n    \"@types/node\": \"^24.0.0\",\n    \"typescript\": \"^5.7.0\"\n  }\n}\n"
